/**
 * The ejs templates of the yeoman monorepo generators, rendered to the same
 * string before formatting.
 */
import type { JsonObject } from "../../engine/model.ts";

const htmlEscapes: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&#34;",
  "'": "&#39;",
};

/** `<%= value %>` of ejs */
const escapeHtml = (value: string | undefined): string =>
  value === undefined
    ? ""
    : value.replaceAll(
        /["&'<>]/g,
        (character) => htmlEscapes[character] ?? character,
      );

const generatedHeader =
  "// Generated by pob: do not edit, it is overwritten on each pob run.\n";

/** monorepo/templates/monorepo.rollup.config.mjs.ejs */
export const monorepoRollupConfigTemplate = (
  configLocations: readonly string[],
): string =>
  `${generatedHeader}${configLocations
    .map(
      (location, index) =>
        `import configs${index + 1} from './${escapeHtml(location)}';\n`,
    )
    .join("")}\nexport default [\n  ${configLocations
    .map((_location, index) => `    ...configs${index + 1},\n  `)
    .join("")}];\n`;

/** monorepo/typescript/templates/tsconfig.json.ejs */
export const monorepoTsconfigTemplate = ({
  packagePaths,
  hasTools,
}: {
  packagePaths: readonly string[];
  hasTools: boolean;
}): string =>
  `${generatedHeader}{\n  "files": [],\n  "references": [\n${packagePaths
    .map(
      (packagePath, index) =>
        `    { "path": "${escapeHtml(packagePath)}/tsconfig.json" }${index === packagePaths.length - 1 && !hasTools ? "" : ","}\n`,
    )
    .join(
      "",
    )}${hasTools ? '    { "path": "tsconfig.tools.json" }\n' : ""}  ]\n}\n`;

const toolsExtensions = ["ts", "mts", "cts"] as const;

/** monorepo/typescript/templates/tsconfig.tools.json.ejs */
export const monorepoTsconfigToolsTemplate = ({
  nodeVersion,
  workspaceGlobs,
  packagePathsWithScriptsIncluded,
}: {
  nodeVersion: string;
  workspaceGlobs: readonly string[];
  packagePathsWithScriptsIncluded: readonly string[];
}): string => {
  const workspaceIncludes = workspaceGlobs
    .map((workspaceGlob, index) => {
      const glob = escapeHtml(workspaceGlob);
      const lines = [
        ...toolsExtensions.map(
          (extension) => `    "${glob}/scripts/**/*.${extension}"`,
        ),
        ...toolsExtensions.map(
          (extension) => `    "${glob}/e2e/**/*.${extension}"`,
        ),
      ];
      return `${lines.join(",\n")}${index === workspaceGlobs.length - 1 ? "" : ","}\n`;
    })
    .join("");
  const exclude =
    packagePathsWithScriptsIncluded.length > 0
      ? `  "exclude": [\n${packagePathsWithScriptsIncluded
          .map(
            (packagePath, index) =>
              `    "${escapeHtml(packagePath)}/scripts/**"${index === packagePathsWithScriptsIncluded.length - 1 ? "" : ","}\n`,
          )
          .join("")}  ],\n`
      : "";
  return `${generatedHeader}{
  "extends": [
    "@pob/root/tsconfigs/strict.json",
    "@pob/root/tsconfigs/targets/node-${escapeHtml(nodeVersion)}.json"
  ],
  "include": [
    "*.config.js",
    "*.config.ts",
    "*.config.mts",
    "*.config.cts",
    "scripts/**/*.ts",
    "scripts/**/*.mts",
    "scripts/**/*.cts",
${workspaceIncludes}  ],
${exclude}  "compilerOptions": {
    "noEmit": true,
    "tsBuildInfoFile": "node_modules/.cache/tsc/tsbuildinfo-tools",
    "incremental": true,
    "resolveJsonModule": true
  }
}
`;
};

const readmePackageRow = (pkg: JsonObject): string => {
  const name = (pkg.name ?? "") as string;
  const repository = pkg.repository as JsonObject | string | undefined;
  const directory =
    typeof repository === "object" ? repository.directory : undefined;
  const link = directory || (name.startsWith("@") ? name : `packages/${name}`);
  const badge = pkg.private
    ? ""
    : `<a href="https://npmjs.org/package/${escapeHtml(name)}"><img src="https://img.shields.io/npm/v/${escapeHtml(name)}.svg?style=flat-square"></a> `;
  return `| [${escapeHtml(name)}](${escapeHtml(link as string)}) | ${badge} | ${escapeHtml(pkg.description as string | undefined)}\n`;
};

/** monorepo/workspaces/templates/README.md.ejs, without description */
export const monorepoReadmeTemplate = ({
  title,
  packages,
  content,
}: {
  title: string;
  packages: readonly JsonObject[];
  content: string;
}): string =>
  `<h1 align="center">
  ${escapeHtml(title)}
</h1>

<h3>📦 Packages</h3>

This repository is a monorepo using workspaces.

| Package | Version | Description |
|---------|---------|-------------|
${packages
  .filter((pkg) => !((pkg.name ?? "") as string).endsWith("-example"))
  .map((pkg) => readmePackageRow(pkg))
  .join("")}
${content ? `${content}\n` : ""}`;
